// One-click reports as plain tables, rendered to CSV, HTML, JSON (here) and to PDF and XLSX in
// the browser. Every report carries the same human-verification statement.
import type { CdrRecord, Report, TableSection } from "./types";
import * as A from "./analytics";
import { displayMsisdn } from "./msisdn";
import { fmtDuration, localDateTime } from "./time";
import { lookupNumber } from "./reference";

export const DISCLAIMER =
  "Analytical output generated by Kayak GraphIQ from the records loaded into this case. It shows patterns and leads, not conclusions: every finding requires human verification against the original operator records before it is relied on or disclosed. Cell-site locations are approximate (a cell can cover several kilometres) and number-series lookups show the original allocation only (mobile number portability).";

export const REPORT_KINDS: { id: string; title: string }[] = [
  { id: "summary", title: "Summary report" },
  { id: "frequency", title: "Contact frequency report" },
  { id: "common", title: "Common numbers report" },
  { id: "imei", title: "IMEI and device report" },
  { id: "tower", title: "Tower and location report" },
  { id: "timeline", title: "Timeline report" },
  { id: "meeting", title: "Possible meeting points report" },
];

export interface ReportContext { caseTitle: string; caseRef?: string; tz: string; generatedBy?: string; filterText?: string; opts?: Partial<A.Options> }

export function buildReport(kind: string, records: CdrRecord[], ctx: ReportContext): Report {
  const tz = ctx.tz, o = { ...(ctx.opts || {}), tz };
  const t = (ms: number | null | undefined) => (ms ? localDateTime(ms, tz) : "");
  const n = displayMsisdn;
  const sections: TableSection[] = [];
  const ov = A.overview(records);
  const scope: TableSection = {
    heading: "Scope", columns: ["Item", "Value"],
    rows: [["Case", ctx.caseTitle], ["Reference", ctx.caseRef || ""], ["Records analysed", ov.records], ["Period", `${t(ov.from)} to ${t(ov.to)}`], ["Time zone", tz], ["Filter", ctx.filterText || "all records"], ["Targets", ov.targets.slice(0, 10).map((x) => n(x.number)).join(", ")]],
  };
  sections.push(scope);
  switch (kind) {
    case "summary": {
      const s = A.summaryByNumber(records, o);
      sections.push({ heading: "Per-number summary", columns: ["Number", "Records", "Calls out", "Calls in", "SMS out", "SMS in", "Missed", "Talk time", "Average", "Longest", "Unique contacts", "In/out ratio", "First", "Last"],
        rows: s.map((x) => [n(x.number), x.records, x.callsOut, x.callsIn, x.smsOut, x.smsIn, x.missed, fmtDuration(x.durTotal), fmtDuration(x.durAvg), fmtDuration(x.durMax), x.uniqueContacts, x.inOutRatio ?? "", t(x.first), t(x.last)]) });
      const tp = A.timeProfile(records, o);
      sections.push({ heading: "When activity happens", columns: ["Measure", "Records", "Share"], rows: [["Day", tp.day], ["Night", tp.night], ["Weekdays", tp.weekdays], ["Weekends", tp.weekend], ["Business hours", tp.business], ["Outside business hours", tp.outside]].map(([k, v]) => [k, v, pct(Number(v), records.length)]) });
      sections.push({ heading: "Peak hours", columns: ["Hour", "Records"], rows: tp.peakHours.map((p) => [`${String(p.h).padStart(2, "0")}:00`, p.n]) });
      const an = A.anomalies(records, o);
      if (an.days.length) sections.push({ heading: "Unusual days (daily volume z-score)", columns: ["Number", "Day", "Records", "Average", "z"], rows: an.days.map((d) => [n(d.a), d.day, d.n, d.mean, d.z]) });
      break;
    }
    case "frequency": {
      const c = A.contacts(records, o);
      sections.push({ heading: "Contacts by frequency", columns: ["A party", "B party", "B party type", "Total", "Calls out", "Calls in", "SMS out", "SMS in", "Missed", "Talk time", "Days", "First", "Last"],
        rows: c.slice(0, 500).map((x) => [n(x.a), n(x.b), lookupNumber(x.b).kind, x.total, x.out, x.in, x.smsOut, x.smsIn, x.missed, fmtDuration(x.dur), x.days, t(x.first), t(x.last)]) });
      const r = A.repeatedCalls(records, o);
      if (r.length) sections.push({ heading: "Repeated calls in a short window", columns: ["A party", "B party", "Most calls in window", "Window start", "Total calls"], rows: r.map((x) => [n(x.a), n(x.b), x.max, t(x.at), x.total]) });
      const ow = A.oneWay(records, o);
      if (ow.length) sections.push({ heading: "One-way contact", columns: ["A party", "B party", "Direction", "Records"], rows: ow.map((x) => [n(x.a), n(x.b), x.direction, x.n]) });
      break;
    }
    case "common": {
      sections.push({ heading: "Numbers in contact with two or more targets", columns: ["Number", "Targets", "Records"], rows: A.commonNumbers(records, o).map((x) => [n(x.b), x.targets.map(n).join(", "), x.n]) });
      sections.push({ heading: "Direct contact between targets", columns: ["A party", "B party", "Total", "Talk time", "First", "Last"], rows: A.targetToTarget(records, o).map((x) => [n(x.a), n(x.b), x.total, fmtDuration(x.dur), t(x.first), t(x.last)]) });
      const circ = A.circular(records, o);
      if (circ.length) sections.push({ heading: "Circular communication (A to B to C to A)", columns: ["Chain", "Started", "Completed"], rows: circ.map((x) => [x.path.map(n).join(" > "), t(x.start), t(x.end)]) });
      break;
    }
    case "imei": {
      const im = A.imeiAnalysis(records, o);
      sections.push({ heading: "One IMEI used with several SIMs", columns: ["IMEI", "TAC", "SIMs (first to last use)"], rows: im.oneImeiManySims.map((x) => [x.imei, x.tac, x.sims.map((s) => `${n(s.id)} (${t(s.first)} to ${t(s.last)}, ${s.n})`).join("; ")]) });
      sections.push({ heading: "One SIM used in several handsets", columns: ["Number", "IMEIs (first to last use)"], rows: im.oneSimManyImeis.map((x) => [n(x.msisdn), x.imeis.map((s) => `${s.id} (${t(s.first)} to ${t(s.last)}, ${s.n})`).join("; ")]) });
      sections.push({ heading: "Device-change timeline", columns: ["Number", "IMEI", "From", "To", "Records"], rows: im.timeline.flatMap((x) => x.segments.map((s) => [n(x.msisdn), s.imei, t(s.from), t(s.to), s.n])) });
      sections.push({ heading: "IMSI, number and IMEI mapping", columns: ["Number", "IMSI", "IMEI", "Records", "First", "Last"], rows: im.mapping.map((x) => [n(x.msisdn), x.imsi, x.imei, x.n, t(x.first), t(x.last)]) });
      break;
    }
    case "tower": {
      const tw = A.towerAnalysis(records, o);
      sections.push({ heading: "Most used cells", columns: ["Number", "Cell", "Records", "Day", "Night", "First", "Last"], rows: tw.byNumber.flatMap((x) => x.cells.slice(0, 15).map((c) => [n(x.a), c.cell, c.n, c.day, c.night, t(c.first), t(c.last)])) });
      sections.push({ heading: "Likely day and night locations (most used cell)", columns: ["Number", "Day cell", "Night cell", "Distinct cells"], rows: tw.byNumber.map((x) => [n(x.a), x.likelyDay, x.likelyNight, x.distinct]) });
      sections.push({ heading: "First and last cell of each day", columns: ["Number", "Day", "First record", "First cell", "Last record", "Last cell"], rows: A.firstLastPerDay(records, o).map((x) => [n(x.a), x.day, t(x.first), x.firstCell, t(x.last), x.lastCell]) });
      sections.push({ heading: "Most common movements between cells", columns: ["Number", "From cell", "To cell", "Times"], rows: tw.transitions.map((x) => [n(x.a), x.from, x.to, x.n]) });
      const rd = A.roamingAndIsd(records, o);
      if (rd.roaming.length) sections.push({ heading: "Roaming", columns: ["Number", "Network or circle", "Records", "First", "Last"], rows: rd.roaming.map((x) => [n(x.a), x.network, x.n, t(x.first), t(x.last)]) });
      break;
    }
    case "timeline": {
      const rs = [...records].sort((a, b) => a.ts - b.ts).slice(0, 5000);
      sections.push({ heading: "Chronology", note: records.length > 5000 ? `First 5,000 of ${records.length} records.` : undefined, columns: ["Date and time", "A party", "Type", "B party", "Duration", "Cell", "IMEI", "Source"],
        rows: rs.map((r) => [t(r.ts), n(r.a), r.type, n(r.b), fmtDuration(r.dur), r.cell || "", r.imei || "", r.src ? `${r.src}:${r.row}` : ""]) });
      const s = A.silentPeriods(records, o);
      if (s.length) sections.push({ heading: "Silent periods", columns: ["Number", "From", "To", "Hours"], rows: s.map((x) => [n(x.a), t(x.from), t(x.to), x.hours]) });
      break;
    }
    case "meeting": {
      const c = A.coLocation(records, o);
      sections.push({ heading: "Two numbers at the same cell within the time window", note: `Window ${o.colocWindowMin ?? A.DEFAULTS.colocWindowMin} minutes. The same cell does not prove the same place.`, columns: ["Number 1", "Number 2", "Cell", "Time 1", "Time 2", "Gap (min)", "Observations"],
        rows: c.map((x) => [n(x.a1), n(x.a2), x.cell, t(x.t1), t(x.t2), x.gapMin, x.n]) });
      const ov2 = A.overlappingCalls(records, o);
      if (ov2.length) sections.push({ heading: "Overlapping calls (possible conference or call waiting)", columns: ["Number", "First call with", "Second call with", "Second call at", "Overlap (s)"], rows: ov2.map((x) => [n(x.a), n(x.b1), n(x.b2), t(x.t2), x.overlapSec]) });
      break;
    }
    default:
      throw new Error("Unknown report type.");
  }
  const title = REPORT_KINDS.find((k) => k.id === kind)?.title || "Report";
  return { kind, title, subtitle: ctx.caseTitle, generatedAt: new Date().toISOString(), sections, disclaimer: DISCLAIMER };
}

const pct = (a: number, b: number) => (b ? `${Math.round((a / b) * 1000) / 10}%` : "0%");

const csvCell = (v: unknown) => {
  let s = String(v ?? "");
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; // stop spreadsheet formula injection
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
export const toCsv = (rows: (string | number)[][]) => rows.map((r) => r.map(csvCell).join(",")).join("\r\n") + "\r\n";

export function reportToCsv(r: Report): string {
  const out: (string | number)[][] = [[r.title], [r.subtitle || ""], [`Generated ${r.generatedAt}`], [r.disclaimer], []];
  for (const s of r.sections) { out.push([s.heading]); if (s.note) out.push([s.note]); out.push(s.columns, ...s.rows, []); }
  return toCsv(out);
}

const h = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);

/** Self-contained HTML report (no scripts, no external files). `charts` are SVG strings placed after the scope table. */
export function reportToHtml(r: Report, charts: { title: string; svg: string }[] = []): string {
  const chartHtml = charts.map((c) => `<figure class="chart">${c.svg}<figcaption>${h(c.title)}</figcaption></figure>`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${h(r.title)} - ${h(r.subtitle)}</title>
<style>body{font:14px/1.5 Arial,Helvetica,sans-serif;color:#0E2F3C;margin:32px;max-width:1200px}h1{font-size:24px;margin:0 0 4px}h2{font-size:16px;margin:28px 0 8px;border-bottom:2px solid #EE9B1E;padding-bottom:4px}
.meta{color:#4E6470;margin:0 0 16px}.note{background:#FBEBCD;border-left:3px solid #9C630E;padding:10px 12px;margin:12px 0}table{border-collapse:collapse;width:100%;font-size:12px}th{background:#0E2F3C;color:#fff;text-align:left;padding:6px 8px}
td{padding:5px 8px;border-bottom:1px solid #D4DEE2;vertical-align:top}tr:nth-child(even) td{background:#F7FAF9}.chart{margin:16px 0;break-inside:avoid}.chart svg{max-width:100%;height:auto}figcaption{font-size:12px;color:#4E6470}footer{margin-top:32px;font-size:12px;color:#4E6470}</style></head><body>
<h1>${h(r.title)}</h1><p class="meta">${h(r.subtitle)} &middot; generated ${h(r.generatedAt)} &middot; Kayak GraphIQ</p><p class="note"><b>Requires human verification.</b> ${h(r.disclaimer)}</p>
${r.sections.map((s, i) => `<h2>${h(s.heading)}</h2>${s.note ? `<p>${h(s.note)}</p>` : ""}<table><thead><tr>${s.columns.map((c) => `<th>${h(c)}</th>`).join("")}</tr></thead><tbody>${s.rows.map((row) => `<tr>${row.map((c) => `<td>${h(c)}</td>`).join("")}</tr>`).join("") || `<tr><td colspan="${s.columns.length}">None found.</td></tr>`}</tbody></table>${i === 0 ? chartHtml : ""}`).join("\n")}
<footer>Kayak GraphIQ, designed and developed by Kayak Strategic Advisors. ${h(r.disclaimer)}</footer></body></html>`;
}

export function reportToJson(r: Report): string { return JSON.stringify(r, null, 1); }

/** KML (Google Earth) for cells with coordinates and, optionally, the movement path of one number. */
export function toKml(points: { name: string; lat: number; lon: number; description?: string; when?: number }[], path?: { name: string; coords: [number, number][] }): string {
  const x = (s: unknown) => String(s ?? "").replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c]!);
  return `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>Kayak GraphIQ export</name><description>${x(DISCLAIMER)}</description>
${points.map((p) => `<Placemark><name>${x(p.name)}</name>${p.description ? `<description>${x(p.description)}</description>` : ""}${p.when ? `<TimeStamp><when>${new Date(p.when).toISOString()}</when></TimeStamp>` : ""}<Point><coordinates>${p.lon},${p.lat},0</coordinates></Point></Placemark>`).join("\n")}
${path && path.coords.length > 1 ? `<Placemark><name>${x(path.name)}</name><LineString><tessellate>1</tessellate><coordinates>${path.coords.map(([lat, lon]) => `${lon},${lat},0`).join(" ")}</coordinates></LineString></Placemark>` : ""}
</Document></kml>`;
}
